// The player setup a simulation starts from, shared by src/worker.js (the simulation) and the
// Combat Stats panel in src/main.js, so the panel shows the stats the engine uses at time 0.
import Player from "./combatsimulator/player";
import Zone from "./combatsimulator/zone";
import Labyrinth from "./combatsimulator/labyrinth";
import { scaleConsumableBuff, scaleAbilityBuff } from "./combatsimulator/buffScaling";

// Buffs from the page's extra toggles: Moo Pass, community buffs and personal buffs (seals).
export function buildExtraBuffs(extra) {
    let extraBuffs = [];
    if (extra.mooPass) {
        const mooPassBuff = {
            "uniqueHrid": "/buff_uniques/experience_moo_pass_buff",
            "typeHrid": "/buff_types/wisdom",
            "ratioBoost": 0,
            "ratioBoostLevelBonus": 0,
            "flatBoost": 0.05,
            "flatBoostLevelBonus": 0,
            "startTime": "0001-01-01T00:00:00Z",
            "duration": 0
        };
        extraBuffs.push(mooPassBuff);
    }
    if (extra.comExp > 0) {
        const comExpBuff = {
            "uniqueHrid": "/buff_uniques/experience_community_buff",
            "typeHrid": "/buff_types/wisdom",
            "ratioBoost": 0,
            "ratioBoostLevelBonus": 0,
            "flatBoost": 0.005 * (extra.comExp - 1) + 0.2,
            "flatBoostLevelBonus": 0,
            "startTime": "0001-01-01T00:00:00Z",
            "duration": 0
        };
        extraBuffs.push(comExpBuff);
    }
    if (extra.comDrop > 0) {
        const comDropBuff = {
            "uniqueHrid": "/buff_uniques/combat_community_buff",
            "typeHrid": "/buff_types/combat_drop_quantity",
            "ratioBoost": 0,
            "ratioBoostLevelBonus": 0,
            "flatBoost": 0.005 * (extra.comDrop - 1) + 0.2,
            "flatBoostLevelBonus": 0,
            "startTime": "0001-01-01T00:00:00Z",
            "duration": 0
        };
        extraBuffs.push(comDropBuff);
    }
    if (extra.personalBuffs) {
        const personalBuffs = {
            "/items/seal_of_attack_speed": {
                "uniqueHrid": "/buff_uniques/personal_attack_speed",
                "typeHrid": "/buff_types/attack_speed",
                "ratioBoost": 0.15,
                "ratioBoostLevelBonus": 0,
                "flatBoost": 0,
                "flatBoostLevelBonus": 0,
                "startTime": "0001-01-01T00:00:00Z",
                "duration": 0
            },
            "/items/seal_of_cast_speed": {
                "uniqueHrid": "/buff_uniques/personal_cast_speed",
                "typeHrid": "/buff_types/cast_speed",
                "ratioBoost": 0,
                "ratioBoostLevelBonus": 0,
                "flatBoost": 0.15,
                "flatBoostLevelBonus": 0,
                "startTime": "0001-01-01T00:00:00Z",
                "duration": 0
            },
            "/items/seal_of_combat_drop": {
                "uniqueHrid": "/buff_uniques/personal_combat_drop",
                "typeHrid": "/buff_types/combat_drop_quantity",
                "ratioBoost": 0,
                "ratioBoostLevelBonus": 0,
                "flatBoost": 0.15,
                "flatBoostLevelBonus": 0,
                "startTime": "0001-01-01T00:00:00Z",
                "duration": 0
            },
            "/items/seal_of_critical_rate": {
                "uniqueHrid": "/buff_uniques/personal_critical_rate",
                "typeHrid": "/buff_types/critical_rate",
                "ratioBoost": 0,
                "ratioBoostLevelBonus": 0,
                "flatBoost": 0.1,
                "flatBoostLevelBonus": 0,
                "startTime": "0001-01-01T00:00:00Z",
                "duration": 0
            },
            "/items/seal_of_damage": {
                "uniqueHrid": "/buff_uniques/personal_damage",
                "typeHrid": "/buff_types/damage",
                "ratioBoost": 0.08,
                "ratioBoostLevelBonus": 0,
                "flatBoost": 0,
                "flatBoostLevelBonus": 0,
                "startTime": "0001-01-01T00:00:00Z",
                "duration": 0
            },
            "/items/seal_of_rare_find": {
                "uniqueHrid": "/buff_uniques/personal_rare_find",
                "typeHrid": "/buff_types/rare_find",
                "ratioBoost": 0,
                "ratioBoostLevelBonus": 0,
                "flatBoost": 0.6,
                "flatBoostLevelBonus": 0,
                "startTime": "0001-01-01T00:00:00Z",
                "duration": 0
            },
            "/items/seal_of_wisdom": {
                "uniqueHrid": "/buff_uniques/personal_wisdom",
                "typeHrid": "/buff_types/wisdom",
                "ratioBoost": 0,
                "ratioBoostLevelBonus": 0,
                "flatBoost": 0.2,
                "flatBoostLevelBonus": 0,
                "startTime": "0001-01-01T00:00:00Z",
                "duration": 0
            }
        };
        for (let buff of extra.personalBuffs) {
            if (personalBuffs[buff]) {
                extraBuffs.push(personalBuffs[buff]);
            }
        }
    }
    return extraBuffs;
}

// zoneSpec: { zoneHrid, difficultyTier } or null; labyrinthSpec: { labyrinthHrid, roomLevel, crates } or null.
export function createZoneAndLabyrinth(zoneSpec, labyrinthSpec) {
    let zone = null;
    if (zoneSpec) {
        zone = new Zone(zoneSpec.zoneHrid, zoneSpec.difficultyTier);
    }
    let labyrinth = null;
    if (labyrinthSpec) {
        labyrinth = new Labyrinth(labyrinthSpec.labyrinthHrid, labyrinthSpec.roomLevel, labyrinthSpec.crates);
    }
    return { zone, labyrinth };
}

// The engine player for one player DTO, with the zone (or labyrinth) buffs and the extra buffs.
export function createSimPlayer(playerDTO, zone, labyrinth, extraBuffs) {
    let simPlayer = Player.createFromDTO(structuredClone(playerDTO));
    simPlayer.zoneBuffs = zone?.buffs || labyrinth?.buffs || [];
    simPlayer.extraBuffs = extraBuffs;
    return simPlayer;
}

// What CombatSimulator.processCombatStartEvent does to each player at the first combat start (time 0):
// permanent buffs (houses, labyrinth upgrades, guild, achievements, zone, extra), then reset → clearBuffs.
export function startPlayerAtTimeZero(simPlayer) {
    simPlayer.generatePermanentBuffs();
    simPlayer.reset(0);
    return simPlayer;
}

// What the combat does in its first seconds with the player's slotted drinks and equipped auras: every drink's
// buffs (scaled by drink concentration) and every aura's buffs (scaled by the caster's effective skill level, taken
// after the drinks) are on the player. Assumes each drink and aura is active; their triggers are not evaluated.
// Auras of other players are not included (the panel shows one player). Same scaling code as the combat (buffScaling.js).
export function applyDrinksAndAuras(simPlayer) {
    for (const drink of simPlayer.drinks) {
        if (!drink) continue;
        for (const buff of drink.buffs) {
            simPlayer.addBuff(scaleConsumableBuff(buff, drink, simPlayer.combatDetails.combatStats.drinkConcentration), 0);
        }
    }
    for (const ability of simPlayer.abilities) {
        if (!ability || !ability.isSpecialAbility) continue;
        for (const effect of ability.abilityEffects) {
            if (effect.effectType != "/ability_effect_types/buff" || effect.targetType != "allAllies") continue;
            for (const buff of effect.buffs) {
                simPlayer.addBuff(scaleAbilityBuff(buff, ability, simPlayer), 0);
            }
        }
    }
    return simPlayer;
}

// The visible player's combat stats as the engine has them at time 0, with the slotted drinks and equipped auras on
// (withDrinksAndAuras, the default) as they are a few seconds into a fight, or without them (equipment and permanent buffs only).
export function getTimeZeroPlayer(playerDTO, zoneSpec, labyrinthSpec, extra, withDrinksAndAuras = true) {
    const { zone, labyrinth } = createZoneAndLabyrinth(zoneSpec, labyrinthSpec);
    const simPlayer = startPlayerAtTimeZero(createSimPlayer(playerDTO, zone, labyrinth, buildExtraBuffs(extra)));
    return withDrinksAndAuras ? applyDrinksAndAuras(simPlayer) : simPlayer;
}
